[CmdletBinding()]
param (
    [switch]$Delete,
    [switch]$Detailed
)

Write-Host "🔎 Mapeando Aplicativos Instalados (Scoop, Registry, Portables)..." -ForegroundColor Cyan

# Lista base de exclusões (Pastas vitais do Windows, Drivers, etc.)
$systemFolders = @(
    "microsoft", "windows", "google", "mozilla", "intel", "nvidia", "amd", 
    "packages", "temp", "crashdumps", "comms", "connecteddevicesplatform",
    "programs", "cache", "local", "roaming", "history", "identitycrl",
    "code", "github", "slack", "discord", "spotify", "vscode"
)

$installedApps = @()

# 1. Mapear apps do Scoop
$scoopPath = "C:\apps\scoop\apps"
if (Test-Path $scoopPath) {
    $scoopApps = (Get-ChildItem $scoopPath -Directory).Name
    $installedApps += $scoopApps
}

# 2. Mapear apps do Registro (Windows Installer)
$regPaths = @(
    "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*",
    "HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*",
    "HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*"
)
foreach ($path in $regPaths) {
    $keys = Get-ItemProperty $path -ErrorAction SilentlyContinue
    foreach ($k in $keys) {
        if ($k.DisplayName) { $installedApps += $k.DisplayName }
        if ($k.Publisher) { $installedApps += $k.Publisher }
    }
}

# 3. Mapear binários e ferramentas em PATH conhecidos (Mise, .tools, bin)
$binPaths = @("C:\bin", "C:\.tools", "C:\data\mise\installs", "C:\data\python")
foreach ($bp in $binPaths) {
    if (Test-Path $bp) {
        $installedApps += (Get-ChildItem $bp -Directory -ErrorAction SilentlyContinue).Name
    }
}

# Normalizar a lista para facilitar o match (tudo minúsculo, sem espaços)
$normalizedApps = @()
foreach ($app in $installedApps) {
    if (-not [string]::IsNullOrWhiteSpace($app)) {
        $lower = $app.ToLower().Trim()
        $normalizedApps += $lower
        $normalizedApps += $lower.Replace(" ","")

        # Pega a primeira palavra se for maior que 2 caracteres (ex: "Adobe Acrobat" -> "adobe")
        $firstWord = $lower.Split(' ')[0]
        if ($firstWord.Length -gt 2) {
            $normalizedApps += $firstWord
        }
    }
}
# Adicionar as pastas vitais ao whitelist
$normalizedApps += $systemFolders
$normalizedApps = $normalizedApps | Select-Object -Unique

Write-Host "✅ Foram identificadas $($normalizedApps.Count) assinaturas únicas de apps instalados." -ForegroundColor Green
Write-Host "🕵️‍♂️ Analisando AppData\Local e AppData\Roaming em busca de órfãos..." -ForegroundColor Cyan

$appDataPaths = @($env:LOCALAPPDATA, $env:APPDATA)
$orphanedFolders = @()

foreach ($basePath in $appDataPaths) {
    $folders = Get-ChildItem $basePath -Directory -ErrorAction SilentlyContinue
    foreach ($folder in $folders) {
        $folderNameLower = $folder.Name.ToLower().Replace(" ","")
        $isOrphan = $true

        foreach ($app in $normalizedApps) {
            # Regras de match flexíveis, mas seguras:
            # 1. Nome da pasta do AppData é igual ao app instalado
            # 2. Nome da pasta do AppData começa com o nome do app instalado
            # 3. Nome do App instalado começa com o nome da pasta (útil para publishers)
            if ($folderNameLower -eq $app -or $folderNameLower.StartsWith($app) -or $app.StartsWith($folderNameLower)) {
                $isOrphan = $false
                break
            }
        }

        if ($isOrphan) {
            $orphanedFolders += $folder
        }
    }
}

Write-Host "`n=== 🧹 Pastas Órfãs Encontradas (Sem app correspondente) ===" -ForegroundColor Yellow
if ($orphanedFolders.Count -eq 0) {
    Write-Host "Nenhuma pasta órfã encontrada! Seu AppData está limpo." -ForegroundColor Green
} else {
    foreach ($orphan in $orphanedFolders) {
        if ($Detailed) {
            $size = "{0:N2} MB" -f ((Get-ChildItem $orphan.FullName -Recurse -File -ErrorAction SilentlyContinue | Measure-Object -Property Length -Sum).Sum / 1MB)
            Write-Host "[$size] $($orphan.FullName)"
        } else {
            Write-Host $orphan.FullName
        }
    }

    Write-Host "`nTotal de possíveis resíduos identificados: $($orphanedFolders.Count)" -ForegroundColor Cyan

    if ($Delete) {
        $confirm = Read-Host "`nVocê tem certeza que deseja APAGAR permanentemente todas as pastas acima? (s/N)"
        if ($confirm -eq 's' -or $confirm -eq 'S') {
            foreach ($orphan in $orphanedFolders) {
                Write-Host "🗑️ Removendo: $($orphan.FullName)" -ForegroundColor Red
                Remove-Item $orphan.FullName -Recurse -Force -ErrorAction SilentlyContinue
            }
            Write-Host "Limpeza concluída!" -ForegroundColor Green
        } else {
            Write-Host "Operação de exclusão cancelada pelo usuário." -ForegroundColor Yellow
        }
    } else {
        Write-Host "`n👉 Para apagar essas pastas, execute o script com a flag: -Delete" -ForegroundColor Gray
        Write-Host "👉 Para ver o tamanho de cada pasta, execute com a flag: -Detailed" -ForegroundColor Gray
    }
}

